using System;using System.Collections.Generic;namespace AshkanSocial.Core.Services{[Serializable]public sealed class RealtimeOutboxItem{public string Id{get;set;}public string Kind{get;set;}public string TargetId{get;set;}public string Text{get;set;}public DateTime CreatedAt{get;set;}=DateTime.Now;public int Attempts{get;set;}}public sealed class RealtimeOutbox{readonly List<RealtimeOutboxItem> items=new List<RealtimeOutboxItem>();public IReadOnlyList<RealtimeOutboxItem> Items=>items.AsReadOnly();public void Enqueue(RealtimeOutboxItem item){if(item!=null)items.Add(item);}public void Remove(string id){items.RemoveAll(x=>x.Id==id);}public void MarkAttempt(string id){var x=items.Find(a=>a.Id==id);if(x!=null)x.Attempts++;}}}